1	use actix_web::{cookie::Cookie, get, post, web, HttpRequest, HttpResponse};
2	use chrono::{DateTime, Duration, Utc};
3	use serde::{Deserialize, Serialize};
4	use sqlx::PgPool;
5	use uuid::Uuid;
6	
7	use crate::error::ApiAppError;
8	use crate::security::{
9	    constants::*,
10	    password,
11	    rbac,
12	    sessions::SessionService,
13	    tokens::ApiTokenService,
14	};
15	
16	#[derive(Deserialize)]
17	pub struct LoginInput {
18	    pub email: String,
19	    pub password: String,
20	}
21	
22	#[derive(Serialize)]
23	pub struct LoginResponse {
24	    pub user_id: Uuid,
25	    pub email: String,
26	    pub roles: Vec<String>,
27	    pub api_token: String,
28	    pub signing_key: String,
29	    pub token_expires_at: DateTime<Utc>,
30	}
31	
32	#[derive(Serialize)]
33	pub struct SessionResponse {
34	    pub principal: rbac::Principal,
35	    pub token_expires_at: Option<DateTime<Utc>>,
36	}
