38	fn client_ip(req: &HttpRequest) -> String {
39	    req.headers()
40	        .get("x-forwarded-for")
41	        .and_then(|h| h.to_str().ok())
42	        .and_then(|v| v.split(',').next())
43	        .map(|s| s.trim().to_string())
44	        .or_else(|| req.connection_info().realip_remote_addr().map(|s| s.to_string()))
45	        .unwrap_or_else(|| "unknown".into())
46	}
47	
48	#[post("/auth/login")]
49	pub async fn login(
50	    pool: web::Data<PgPool>,
51	    body: web::Json<LoginInput>,
52	    req: HttpRequest,
53	) -> Result<HttpResponse, ApiAppError> {
54	    let ip = client_ip(&req);
55	    let email = body.email.trim().to_lowercase();
56	
57	    // Look up user (existence not revealed in error messages).
58	    let row: Option<(Uuid, String, Option<String>, bool)> = sqlx::query_as(
59	        "SELECT id, email, password_hash, is_active FROM users WHERE lower(email) = $1",
60	    )
61	    .bind(&email)
62	    .fetch_optional(pool.get_ref())
63	    .await?;
64	
65	    // Check active lockout BEFORE password verification — never reveal whether
66	    // the account exists, but consistently reject locked accounts.
67	    if let Some((user_id, _, _, _)) = &row {
68	        let lock: Option<(DateTime<Utc>,)> =
69	            sqlx::query_as("SELECT locked_until FROM account_lockouts WHERE user_id = $1")
70	                .bind(user_id)
71	                .fetch_optional(pool.get_ref())
72	                .await?;
73	        if let Some((until,)) = lock {
74	            if until > Utc::now() {
75	                record_attempt(pool.get_ref(), &email, false, &ip).await?;
76	                return Err(ApiAppError::Unauthorized("account locked".into()));
77	            }
78	        }
79	    }
80	
81	    let ok = match &row {
82	        Some((_, _, Some(hash), true)) => password::verify_password(&body.password, hash),
83	        _ => false,
84	    };
85	
86	    record_attempt(pool.get_ref(), &email, ok, &ip).await?;
87	
88	    if !ok {
89	        if let Some((user_id, _, _, _)) = &row {
90	            // Count recent failures inside the lockout window.
91	            let since = Utc::now() - Duration::from_std(LOCKOUT).unwrap();
92	            let count: (i64,) = sqlx::query_as(
93	                "SELECT COUNT(*) FROM login_attempts
94	                 WHERE lower(email) = $1 AND success = FALSE AND occurred_at >= $2",
95	            )
96	            .bind(&email)
97	            .bind(since)
98	            .fetch_one(pool.get_ref())
99	            .await?;
100	            if count.0 >= MAX_FAILED_LOGINS {
101	                let until = Utc::now() + Duration::from_std(LOCKOUT).unwrap();
102	                sqlx::query(
103	                    "INSERT INTO account_lockouts (user_id, locked_until) VALUES ($1, $2)
104	                     ON CONFLICT (user_id) DO UPDATE SET locked_until = EXCLUDED.locked_until,
105	                                                          created_at = NOW()",
106	                )
107	                .bind(user_id)
108	                .bind(until)
109	                .execute(pool.get_ref())
110	                .await?;
111	            }
112	        }
113	        return Err(ApiAppError::Unauthorized("invalid credentials".into()));
114	    }
115	
116	    let (user_id, db_email, _, _) = row.unwrap();
117	
118	    // Successful login: clear stale lockouts.
119	    sqlx::query("DELETE FROM account_lockouts WHERE user_id = $1")
120	        .bind(user_id)
121	        .execute(pool.get_ref())
122	        .await?;
123	
124	    let session_token = SessionService::create(pool.get_ref(), user_id).await?;
125	    let issued = ApiTokenService::issue(pool.get_ref(), user_id).await?;
126	    let principal = rbac::load_principal(pool.get_ref(), user_id).await?;
127	
128	    let secure = std::env::var("COOKIE_SECURE").map(|v| v == "true").unwrap_or(false);
129	    let cookie = Cookie::build(SESSION_COOKIE, session_token)
130	        .http_only(true)
131	        .secure(secure)
132	        .same_site(actix_web::cookie::SameSite::Lax)
133	        .path("/")
134	        .finish();
135	
136	    Ok(HttpResponse::Ok().cookie(cookie).json(LoginResponse {
137	        user_id,
138	        email: db_email,
139	        roles: principal.roles,
140	        api_token: issued.token,
141	        signing_key: issued.signing_key,
142	        token_expires_at: issued.expires_at,
143	    }))
144	}
145	
146	async fn record_attempt(pool: &PgPool, email: &str, success: bool, ip: &str) -> Result<(), ApiAppError> {
147	    sqlx::query("INSERT INTO login_attempts (email, success, ip) VALUES ($1, $2, $3)")
148	        .bind(email)
149	        .bind(success)
150	        .bind(ip)
151	        .execute(pool)
152	        .await?;
153	    Ok(())
154	}
155	
156	#[post("/auth/logout")]
157	pub async fn logout(pool: web::Data<PgPool>, req: HttpRequest) -> Result<HttpResponse, ApiAppError> {
158	    if let Some(c) = req.cookie(SESSION_COOKIE) {
159	        SessionService::revoke(pool.get_ref(), c.value()).await?;
160	    }
161	    // Also revoke any active API tokens for the session's user, if known.
162	    if let Some(c) = req.cookie(SESSION_COOKIE) {
163	        if let Ok(Some(info)) = SessionService::lookup(pool.get_ref(), c.value()).await {
164	            ApiTokenService::revoke_for_user(pool.get_ref(), info.user_id).await?;
165	        }
166	    }
167	    Ok(HttpResponse::Ok()
168	        .cookie(Cookie::build(SESSION_COOKIE, "").path("/").max_age(actix_web::cookie::time::Duration::ZERO).finish())
169	        .json(serde_json::json!({"ok": true})))
170	}
171	
172	#[get("/auth/session")]
173	pub async fn current_session(
174	    pool: web::Data<PgPool>,
175	    req: HttpRequest,
176	) -> Result<HttpResponse, ApiAppError> {
177	    let cookie = req
178	        .cookie(SESSION_COOKIE)
179	        .ok_or_else(|| ApiAppError::Unauthorized("no session".into()))?;
180	    let info = SessionService::lookup(pool.get_ref(), cookie.value())
181	        .await?
182	        .ok_or_else(|| ApiAppError::Unauthorized("no session".into()))?;
183	    let principal = rbac::load_principal(pool.get_ref(), info.user_id).await?;
184	    Ok(HttpResponse::Ok().json(SessionResponse { principal, token_expires_at: None }))
185	}
186	
187	// ---- admin-mediated recovery (no email/SMS) ----
188	#[derive(Deserialize)]
189	pub struct RecoveryRequestInput {
190	    pub email: String,
191	}
192	
193	#[post("/auth/recovery/request")]
194	pub async fn request_recovery(
195	    pool: web::Data<PgPool>,
196	    body: web::Json<RecoveryRequestInput>,
197	) -> Result<HttpResponse, ApiAppError> {
198	    let user: Option<(Uuid,)> = sqlx::query_as("SELECT id FROM users WHERE lower(email) = $1")
199	        .bind(body.email.trim().to_lowercase())
200	        .fetch_optional(pool.get_ref())
201	        .await?;
202	    // Always respond OK to avoid user-enumeration.
203	    if let Some((id,)) = user {
204	        sqlx::query("INSERT INTO recovery_requests (user_id) VALUES ($1)")
205	            .bind(id)
206	            .execute(pool.get_ref())
207	            .await?;
208	    }
209	    Ok(HttpResponse::Ok().json(serde_json::json!({"ok": true})))
210	}
