1	use anyhow::Result;
2	use chrono::{Duration, Utc};
3	use rand::RngCore;
4	use sha2::{Digest, Sha256};
5	use sqlx::PgPool;
6	use uuid::Uuid;
7	
8	/// Sessions are server-tracked: the cookie value is a high-entropy random
9	/// token, and only its SHA-256 hash is stored in `sessions`. This gives us
10	/// real revocation ("logout invalidates session") without trusting the
11	/// client, and avoids the foot-guns of pure JWT cookies.
12	pub struct SessionService;
13	
14	#[derive(Debug, Clone)]
15	pub struct SessionInfo {
16	    pub user_id: Uuid,
17	    pub session_id: Uuid,
18	}
19	
20	const SESSION_TTL_HOURS: i64 = 12;
21	
22	impl SessionService {
23	    pub fn random_token() -> String {
24	        let mut buf = [0u8; 32];
25	        rand::thread_rng().fill_bytes(&mut buf);
26	        hex::encode(buf)
27	    }
28	
29	    pub fn hash(token: &str) -> String {
30	        let mut h = Sha256::new();
31	        h.update(token.as_bytes());
32	        hex::encode(h.finalize())
33	    }
34	
35	    pub async fn create(pool: &PgPool, user_id: Uuid) -> Result<String> {
36	        let token = Self::random_token();
37	        let token_hash = Self::hash(&token);
38	        let expires_at = Utc::now() + Duration::hours(SESSION_TTL_HOURS);
39	        sqlx::query(
40	            "INSERT INTO sessions (id, user_id, token_hash, expires_at)
41	             VALUES (gen_random_uuid(), $1, $2, $3)",
42	        )
43	        .bind(user_id)
44	        .bind(&token_hash)
45	        .bind(expires_at)
46	        .execute(pool)
47	        .await?;
48	        Ok(token)
49	    }
50	
51	    pub async fn lookup(pool: &PgPool, token: &str) -> Result<Option<SessionInfo>> {
52	        let token_hash = Self::hash(token);
53	        let row: Option<(Uuid, Uuid)> = sqlx::query_as(
54	            "SELECT id, user_id FROM sessions
55	             WHERE token_hash = $1 AND revoked_at IS NULL AND expires_at > NOW()",
56	        )
57	        .bind(&token_hash)
58	        .fetch_optional(pool)
59	        .await?;
60	        Ok(row.map(|(id, user_id)| SessionInfo { user_id, session_id: id }))
61	    }
62	
63	    pub async fn revoke(pool: &PgPool, token: &str) -> Result<()> {
64	        let token_hash = Self::hash(token);
65	        sqlx::query("UPDATE sessions SET revoked_at = NOW() WHERE token_hash = $1")
66	            .bind(&token_hash)
67	            .execute(pool)
68	            .await?;
69	        Ok(())
70	    }
71	}
