1	use anyhow::Result;
2	use chrono::Utc;
3	use rand::RngCore;
4	use sha2::{Digest, Sha256};
5	use sqlx::PgPool;
6	use uuid::Uuid;
7	
8	use super::constants::API_TOKEN_TTL;
9	
10	/// Short-lived API token issued after session login.
11	///
12	/// The token bearer string is stored only as a SHA-256 hash so a database
13	/// leak does not yield usable bearer credentials. The HMAC signing key is
14	/// kept server-side so the API can recompute and verify request signatures.
15	pub struct ApiTokenService;
16	
17	#[derive(Debug, Clone)]
18	pub struct IssuedToken {
19	    pub token: String,
20	    pub signing_key: String,
21	    pub expires_at: chrono::DateTime<Utc>,
22	}
23	
24	#[derive(Debug, Clone)]
25	pub struct TokenContext {
26	    pub user_id: Uuid,
27	    pub signing_key: String,
28	    pub expires_at: chrono::DateTime<Utc>,
29	}
30	
31	fn random_hex(len: usize) -> String {
32	    let mut buf = vec![0u8; len];
33	    rand::thread_rng().fill_bytes(&mut buf);
34	    hex::encode(buf)
35	}
36	
37	pub fn sha256_hex(s: &str) -> String {
38	    let mut h = Sha256::new();
39	    h.update(s.as_bytes());
40	    hex::encode(h.finalize())
41	}
42	
43	impl ApiTokenService {
44	    pub async fn issue(pool: &PgPool, user_id: Uuid) -> Result<IssuedToken> {
45	        let token = random_hex(32);
46	        let signing_key = random_hex(32);
47	        let expires_at = Utc::now() + chrono::Duration::from_std(API_TOKEN_TTL).unwrap();
48	        sqlx::query(
49	            "INSERT INTO api_tokens (user_id, token_hash, signing_key, expires_at)
50	             VALUES ($1, $2, $3, $4)",
51	        )
52	        .bind(user_id)
53	        .bind(sha256_hex(&token))
54	        .bind(&signing_key)
55	        .bind(expires_at)
56	        .execute(pool)
57	        .await?;
58	        Ok(IssuedToken { token, signing_key, expires_at })
59	    }
60	
61	    pub async fn lookup(pool: &PgPool, token: &str) -> Result<Option<TokenContext>> {
62	        let token_hash = sha256_hex(token);
63	        let row: Option<(Uuid, String, chrono::DateTime<Utc>)> = sqlx::query_as(
64	            "SELECT user_id, signing_key, expires_at FROM api_tokens
65	             WHERE token_hash = $1 AND revoked_at IS NULL AND expires_at > NOW()",
66	        )
67	        .bind(&token_hash)
68	        .fetch_optional(pool)
69	        .await?;
70	        Ok(row.map(|(user_id, signing_key, expires_at)| TokenContext {
71	            user_id,
72	            signing_key,
73	            expires_at,
74	        }))
75	    }
