9	/// Materialized authorization context for a request, computed once by the
10	/// auth middleware and read by route handlers via the `Principal` extractor.
11	#[derive(Debug, Clone, Serialize)]
12	pub struct Principal {
13	    pub user_id: Uuid,
14	    pub email: String,
15	    pub roles: Vec<String>,
16	    pub permissions: HashSet<String>,
17	    pub scopes: Vec<Scope>,
18	}
19	
20	#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
21	pub struct Scope {
22	    pub kind: ScopeKind,
23	    pub reference: String,
24	}
25	
26	#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
27	#[serde(rename_all = "snake_case")]
28	pub enum ScopeKind {
29	    Institution,
30	    Site,
31	    Department,
32	    FamilyGroup,
33	}
34	
35	impl ScopeKind {
36	    pub fn as_str(&self) -> &'static str {
37	        match self {
38	            Self::Institution => "institution",
39	            Self::Site => "site",
40	            Self::Department => "department",
41	            Self::FamilyGroup => "family_group",
42	        }
43	    }
44	    pub fn parse(s: &str) -> Option<Self> {
45	        Some(match s {
46	            "institution" => Self::Institution,
47	            "site" => Self::Site,
48	            "department" => Self::Department,
49	            "family_group" => Self::FamilyGroup,
50	            _ => return None,
51	        })
52	    }
53	}
54	
55	impl Principal {
56	    pub fn require(&self, permission: &str) -> Result<(), ApiAppError> {
57	        if self.permissions.contains(permission) || self.permissions.contains("*") {
58	            Ok(())
59	        } else {
60	            Err(ApiAppError::Forbidden(format!("missing permission: {permission}")))
61	        }
62	    }
63	
64	    pub fn has_role(&self, role: &str) -> bool {
65	        self.roles.iter().any(|r| r == role)
66	    }
67	
68	    /// Returns Ok if the principal has any scope of the given kind/reference,
69	    /// or holds the wildcard permission `scope:any`.
70	    pub fn require_scope(&self, kind: ScopeKind, reference: &str) -> Result<(), ApiAppError> {
71	        if self.permissions.contains("scope:any") {
72	            return Ok(());
73	        }
74	        let allowed = self.scopes.iter().any(|s| s.kind == kind && s.reference == reference);
75	        if allowed {
76	            Ok(())
77	        } else {
78	            Err(ApiAppError::Forbidden(format!(
79	                "scope denied: {}={}",
80	                kind.as_str(),
81	                reference
82	            )))
83	        }
84	    }
85	}
86	
87	pub async fn load_principal(pool: &PgPool, user_id: Uuid) -> Result<Principal> {
88	    let user: (Uuid, String) = sqlx::query_as("SELECT id, email FROM users WHERE id = $1 AND is_active")
89	        .bind(user_id)
90	        .fetch_one(pool)
91	        .await?;
92	
93	    let roles: Vec<(String,)> = sqlx::query_as(
94	        "SELECT r.key FROM roles r
95	         JOIN user_role_assignments ura ON ura.role_id = r.id
96	         WHERE ura.user_id = $1",
97	    )
98	    .bind(user_id)
99	    .fetch_all(pool)
100	    .await?;
101	
102	    let perms: Vec<(String,)> = sqlx::query_as(
103	        "SELECT DISTINCT p.key FROM permissions p
104	         JOIN role_permissions rp ON rp.permission_id = p.id
105	         JOIN user_role_assignments ura ON ura.role_id = rp.role_id
106	         WHERE ura.user_id = $1",
107	    )
108	    .bind(user_id)
109	    .fetch_all(pool)
110	    .await?;
111	
112	    let scopes: Vec<(String, String)> = sqlx::query_as(
113	        "SELECT scope_kind, scope_ref FROM user_scopes WHERE user_id = $1",
114	    )
115	    .bind(user_id)
116	    .fetch_all(pool)
117	    .await?;
118	
119	    Ok(Principal {
120	        user_id: user.0,
121	        email: user.1,
122	        roles: roles.into_iter().map(|(k,)| k).collect(),
123	        permissions: perms.into_iter().map(|(k,)| k).collect(),
124	        scopes: scopes
125	            .into_iter()
126	            .filter_map(|(k, r)| ScopeKind::parse(&k).map(|kind| Scope { kind, reference: r }))
127	            .collect(),
128	    })
129	}
