13	pub const LOCKOUT: Duration = Duration::from_secs(15 * 60);
14	
15	/// API token lifetime.
16	pub const API_TOKEN_TTL: Duration = Duration::from_secs(15 * 60);
17	
18	/// Allowed clock skew for signed-request timestamps.
19	pub const REPLAY_WINDOW: Duration = Duration::from_secs(60);
20	
21	/// Per-IP rate limit (sliding window of 60 seconds).
22	/// Overridable via RATE_LIMIT_PER_MIN env var for test environments.
23	pub fn rate_limit_per_min() -> u32 {
24	    std::env::var("RATE_LIMIT_PER_MIN")
25	        .ok()
26	        .and_then(|v| v.parse().ok())
27	        .unwrap_or(120)
28	}
