        let sql = "SELECT COALESCE(SUM(stat_value), 0) FROM analytics_daily \
                   WHERE institution_id = $1 \
                     AND stat_date >= $2 \
                     AND stat_date < $2 + INTERVAL '7 days' \
                     AND stat_key = $3";
        assert!(sql.contains("FROM analytics_daily"));
        assert!(sql.contains("institution_id = $1"));
    }
}
