    fn different_keys_produce_different_signatures() {
        let canon =
            RequestSigner::canonical_string_no_body("GET", "/test", "123", "n");
        let sig1 = RequestSigner::sign("key-one", &canon);
        let sig2 = RequestSigner::sign("key-two", &canon);
        assert_ne!(sig1, sig2);
    }

