10	/// Browser-side signed-request client.
11	///
12	/// Canonical string format (mirrors `security::signing` on the server):
13	///   `METHOD\nPATH\nTIMESTAMP\nNONCE`
14	/// where PATH is the **bare resource path without query string**
15	/// (e.g. `/api/v1/analytics/dashboard` even when called as
16	/// `/api/v1/analytics/dashboard?institution_id=abc`).
17	/// HMAC-SHA256 with the per-token signing key returned at login.
18	pub struct ApiClient {
19	    pub api_token: String,
20	    pub signing_key: String,
21	}
22	
23	fn sign(key: &str, canonical: &str) -> String {
24	    let mut mac = HmacSha256::new_from_slice(key.as_bytes()).expect("hmac");
25	    mac.update(canonical.as_bytes());
26	    hex::encode(mac.finalize().into_bytes())
27	}
