29	impl ApiClient {
30	    pub async fn get(&self, path: &str) -> Result<Response, String> {
31	        self.send("GET", path, None::<&str>).await
32	    }
33	    pub async fn post_json<S: serde::Serialize>(&self, path: &str, body: &S) -> Result<Response, String> {
34	        let body = serde_json::to_string(body).map_err(|e| e.to_string())?;
35	        self.send("POST", path, Some(body.as_str())).await
36	    }
