38	    /// Upload a file as multipart/form-data with the same HMAC signing headers.
39	    pub async fn post_multipart(&self, path: &str, form: FormData) -> Result<Response, String> {
40	        let ts = Utc::now().timestamp().to_string();
41	        let nonce = Uuid::new_v4().to_string();
42	        // Strip query string: only the bare path is signed (contract: PATH excludes '?...').
43	        let sign_path = path.split_once('?').map_or(path, |(p, _)| p);
44	        let canonical = format!("POST\n{}\n{}\n{}", sign_path, ts, nonce);
45	        let sig = sign(&self.signing_key, &canonical);
46	        Request::post(path)
47	            .header("x-silveroak-token", &self.api_token)
48	            .header("x-silveroak-timestamp", &ts)
49	            .header("x-silveroak-nonce", &nonce)
50	            .header("x-silveroak-signature", &sig)
51	            .body(form)
52	            .map_err(|e| e.to_string())?
53	            .send()
54	            .await
55	            .map_err(|e| e.to_string())
56	    }
57	    async fn send(&self, method: &str, path: &str, body: Option<&str>) -> Result<Response, String> {
58	        let ts = Utc::now().timestamp().to_string();
59	        let nonce = Uuid::new_v4().to_string();
60	        // Strip query string: only the bare path is signed (contract: PATH excludes '?...').
61	        let sign_path = path.split_once('?').map_or(path, |(p, _)| p);
62	        let canonical = format!("{}\n{}\n{}\n{}", method, sign_path, ts, nonce);
63	        let sig = sign(&self.signing_key, &canonical);
64	        let builder = match method {
65	            "POST" => Request::post(path),
66	            _ => Request::get(path),
67	        }
68	        .header("x-silveroak-token", &self.api_token)
69	        .header("x-silveroak-timestamp", &ts)
70	        .header("x-silveroak-nonce", &nonce)
71	        .header("x-silveroak-signature", &sig);
72	        let res = if let Some(body) = body {
73	            builder
