131	pub async fn create_draft(
132	    pool: &PgPool,
133	    p: &Principal,
134	    input: CreateRequisitionInput,
135	) -> Result<RequisitionDetail, ApiAppError> {
136	    p.require("requisitions:write")?;
137	    assert_dept_scope(p, input.department_id)?;
138	    if input.needed_by < chrono::Local::now().date_naive() {
139	        return Err(ApiAppError::BadRequest("needed_by must be today or a future date".into()));
140	    }
141	    if input.justification.trim().is_empty() {
142	        return Err(ApiAppError::BadRequest("justification required".into()));
143	    }
144	    if input.lines.is_empty() {
145	        return Err(ApiAppError::BadRequest("at least one line required".into()));
146	    }
147	    for l in &input.lines {
148	        if l.quantity <= 0 {
149	            return Err(ApiAppError::BadRequest("quantities must be > 0".into()));
150	        }
151	    }
152	
153	    let mut tx = pool.begin().await?;
154	
155	    // Derive the site from the department.
156	    let site_row: Option<(Uuid,)> = sqlx::query_as("SELECT site_id FROM departments WHERE id=$1")
157	        .bind(input.department_id).fetch_optional(&mut *tx).await?;
158	    let site_id = site_row.ok_or_else(|| ApiAppError::BadRequest("unknown department".into()))?.0;
159	
160	    // Look up items + categories + on_hand at the requisition's site.
161	    let mut total: i64 = 0;
162	    let mut controlled = false;
163	    let mut prepared: Vec<(Uuid, i32, i64, i64)> = Vec::new();
164	    for l in &input.lines {
165	        let row: Option<(i64, bool)> = sqlx::query_as(
166	            "SELECT i.unit_price_cents, c.controlled
167	             FROM inventory_items i JOIN inventory_categories c ON c.id = i.category_id
168	             WHERE i.id = $1 AND i.is_active",
169	        )
170	        .bind(l.item_id)
171	        .fetch_optional(&mut *tx)
172	        .await?;
173	        let (unit_price, ctrl) = row.ok_or_else(|| ApiAppError::BadRequest("item not found".into()))?;
174	        let line_total = unit_price * l.quantity as i64;
175	        total += line_total;
176	        if ctrl { controlled = true; }
177	        prepared.push((l.item_id, l.quantity, unit_price, line_total));
178	    }
179	
180	    let ref_code = next_ref_code(&mut tx).await?;
181	    let req_id: (Uuid,) = sqlx::query_as(
182	        "INSERT INTO requisitions
183	            (ref_code, requester_id, site_id, department_id, status,
184	             needed_by, justification, total_amount_cents, contains_controlled)
185	         VALUES ($1, $2, $3, $4, 'draft', $5, $6, $7, $8) RETURNING id",
186	    )
187	    .bind(&ref_code)
188	    .bind(p.user_id)
189	    .bind(site_id)
190	    .bind(input.department_id)
191	    .bind(input.needed_by)
192	    .bind(input.justification.trim())
193	    .bind(total)
194	    .bind(controlled)
195	    .fetch_one(&mut *tx)
196	    .await?;
197	
198	    for (item_id, qty, unit_price, line_total) in prepared {
199	        sqlx::query(
200	            "INSERT INTO requisition_lines (requisition_id, item_id, quantity, unit_price_cents, line_total_cents)
201	             VALUES ($1,$2,$3,$4,$5)",
202	        )
203	        .bind(req_id.0).bind(item_id).bind(qty).bind(unit_price).bind(line_total)
204	        .execute(&mut *tx).await?;
205	    }
206	    audit(&mut tx, req_id.0, Some(p.user_id), "created", None).await?;
207	    tx.commit().await?;
208	    load_detail(pool, p, req_id.0).await
209	}
