211	pub async fn submit(
212	    pool: &PgPool,
213	    p: &Principal,
214	    req_id: Uuid,
215	) -> Result<RequisitionDetail, ApiAppError> {
216	    p.require("requisitions:write")?;
217	    let row: Option<(Uuid, String, i64, bool)> = sqlx::query_as(
218	        "SELECT requester_id, status, total_amount_cents, contains_controlled
219	         FROM requisitions WHERE id = $1",
220	    )
221	    .bind(req_id).fetch_optional(pool).await?;
222	    let (requester, status, total, ctrl) = row.ok_or(ApiAppError::NotFound)?;
223	    assert_owner(p, requester)?;
224	    let cur = ReqStatus::parse(&status).unwrap();
225	    Transition::check(cur, ReqStatus::PendingApproval)?;
226	
227	    let workflow_id = load_workflow_id(pool).await?;
228	    let snap = ReqSnapshot { total_amount_cents: total, contains_controlled: ctrl };
229	    let route: Vec<ResolvedNode> = resolve_route(pool, workflow_id, &snap).await?;
230	
231	    let mut tx = pool.begin().await?;
232	    sqlx::query("UPDATE requisitions SET status='pending_approval', workflow_id=$2, submitted_at=NOW(), updated_at=NOW() WHERE id=$1")
233	        .bind(req_id).bind(workflow_id).execute(&mut *tx).await?;
234	    let inst: (Uuid,) = sqlx::query_as(
235	        "INSERT INTO requisition_approval_instances (requisition_id, workflow_id) VALUES ($1,$2) RETURNING id",
236	    ).bind(req_id).bind(workflow_id).fetch_one(&mut *tx).await?;
237	    for (i, n) in route.iter().enumerate() {
238	        sqlx::query(
239	            "INSERT INTO requisition_approval_steps (instance_id, sequence, node_id, required_role)
240	             VALUES ($1, $2, $3, $4)",
241	        )
242	        .bind(inst.0).bind(i as i32 + 1).bind(n.node_id).bind(&n.required_role)
243	        .execute(&mut *tx).await?;
244	    }
245	    audit(&mut tx, req_id, Some(p.user_id), "submitted",
246	          Some(&format!("routed to {} approval node(s)", route.len()))).await?;
247	    tx.commit().await?;
248	    load_detail(pool, p, req_id).await
249	}
