339	/// Single transaction: mark final step approved, mark instance approved,
340	/// move requisition through approved_final → issued, verify stock, deduct
341	/// stock per line, create issue_record + issue_record_lines, append audit.
342	/// Any failure rolls back the entire chain.
343	async fn finalize_in_transaction(
344	    pool: &PgPool,
345	    p: &Principal,
346	    req_id: Uuid,
347	    instance_id: Uuid,
348	    step_id: Uuid,
349	    comment: Option<&str>,
350	) -> Result<(), ApiAppError> {
351	    let mut tx = pool.begin().await?;
352	
353	    // Lock the requisition + its lines.
354	    let req: (String, Uuid) = sqlx::query_as(
355	        "SELECT status, site_id FROM requisitions WHERE id=$1 FOR UPDATE",
356	    ).bind(req_id).fetch_one(&mut *tx).await?;
357	    let cur = ReqStatus::parse(&req.0).unwrap();
358	    Transition::check(cur, ReqStatus::ApprovedFinal)?;
359	    let site_id = req.1;
360	
361	    // Lock + read lines.
362	    let lines: Vec<(Uuid, Uuid, i32, i64, i64)> = sqlx::query_as(
363	        "SELECT id, item_id, quantity, unit_price_cents, line_total_cents
364	         FROM requisition_lines WHERE requisition_id=$1 ORDER BY id",
365	    ).bind(req_id).fetch_all(&mut *tx).await?;
366	
367	    // Verify + deduct stock per line, locking the stock row.
368	    for (_lid, item_id, qty, _, _) in &lines {
369	        let stock: Option<(i32,)> = sqlx::query_as(
370	            "SELECT on_hand FROM inventory_stock_by_site WHERE item_id=$1 AND site_id=$2 FOR UPDATE",
371	        ).bind(item_id).bind(site_id).fetch_optional(&mut *tx).await?;
372	        let on_hand = stock.map(|s| s.0).unwrap_or(0);
373	        if on_hand < *qty {
374	            // Rolls back the whole transaction by returning early.
375	            return Err(ApiAppError::BadRequest(format!(
376	                "insufficient stock for item {item_id}: have {on_hand}, need {qty}"
377	            )));
378	        }
379	        sqlx::query(
380	            "UPDATE inventory_stock_by_site SET on_hand = on_hand - $3 WHERE item_id=$1 AND site_id=$2",
381	        ).bind(item_id).bind(site_id).bind(qty).execute(&mut *tx).await?;
382	    }
383	
384	    // Mark approval step + instance.
385	    sqlx::query(
386	        "UPDATE requisition_approval_steps SET decision='approved', decided_by=$2, decided_at=NOW(), reason=$3 WHERE id=$1",
387	    ).bind(step_id).bind(p.user_id).bind(comment).execute(&mut *tx).await?;
388	    sqlx::query("UPDATE requisition_approval_instances SET status='approved' WHERE id=$1")
389	        .bind(instance_id).execute(&mut *tx).await?;
390	
391	    // approved_final → issued (record both transitions in audit).
392	    sqlx::query("UPDATE requisitions SET status='approved_final', finalized_at=NOW(), updated_at=NOW() WHERE id=$1")
393	        .bind(req_id).execute(&mut *tx).await?;
394	    audit(&mut tx, req_id, Some(p.user_id), "approved_final", comment).await?;
395	
396	    sqlx::query("UPDATE requisitions SET status='issued', updated_at=NOW() WHERE id=$1")
397	        .bind(req_id).execute(&mut *tx).await?;
398	
399	    // Issue record + lines.
400	    let issue: (Uuid,) = sqlx::query_as(
401	        "INSERT INTO issue_records (requisition_id, site_id, issued_by) VALUES ($1,$2,$3) RETURNING id",
402	    ).bind(req_id).bind(site_id).bind(p.user_id).fetch_one(&mut *tx).await?;
403	    for (_lid, item_id, qty, unit_price, line_total) in &lines {
404	        sqlx::query(
405	            "INSERT INTO issue_record_lines (issue_record_id, item_id, quantity, unit_price_cents, line_total_cents)
406	             VALUES ($1,$2,$3,$4,$5)",
407	        ).bind(issue.0).bind(item_id).bind(qty).bind(unit_price).bind(line_total)
408	        .execute(&mut *tx).await?;
409	    }
410	    audit(&mut tx, req_id, Some(p.user_id), "issued",
411	          Some(&format!("issue_record={}", issue.0))).await?;
412	
413	    tx.commit().await?;
414	    Ok(())
415	}
