418	    pool: &PgPool,
419	    p: &Principal,
420	    req_id: Uuid,
421	    input: DecisionInput,
422	) -> Result<RequisitionDetail, ApiAppError> {
423	    p.require("requisitions:approve")?;
424	    let reason = input
425	        .reason
426	        .as_ref()
427	        .map(|s| s.trim())
428	        .filter(|s| !s.is_empty())
429	        .ok_or_else(|| ApiAppError::BadRequest("reject requires reason".into()))?
430	        .to_string();
431	
432	    let (instance_id, step_id, _seq, role) = current_pending_step(pool, req_id).await?;
433	    assert_can_act_at_step(p, &role)?;
434	
435	    let mut tx = pool.begin().await?;
436	    let cur_row: (String,) = sqlx::query_as("SELECT status FROM requisitions WHERE id=$1 FOR UPDATE")
437	        .bind(req_id).fetch_one(&mut *tx).await?;
438	    let cur = ReqStatus::parse(&cur_row.0).unwrap();
439	    Transition::check(cur, ReqStatus::Rejected)?;
440	
441	    sqlx::query("UPDATE requisition_approval_steps SET decision='rejected', decided_by=$2, decided_at=NOW(), reason=$3 WHERE id=$1")
442	        .bind(step_id).bind(p.user_id).bind(&reason).execute(&mut *tx).await?;
443	    sqlx::query("UPDATE requisition_approval_instances SET status='rejected' WHERE id=$1")
444	        .bind(instance_id).execute(&mut *tx).await?;
445	    sqlx::query("UPDATE requisitions SET status='rejected', updated_at=NOW() WHERE id=$1")
446	        .bind(req_id).execute(&mut *tx).await?;
447	    audit(&mut tx, req_id, Some(p.user_id), "rejected", Some(&reason)).await?;
448	    tx.commit().await?;
449	    load_detail(pool, p, req_id).await
450	}
