498	pub async fn approver_inbox(pool: &PgPool, p: &Principal) -> Result<Vec<RequisitionDetail>, ApiAppError> {
499	    p.require("requisitions:approve")?;
500	    // Find all requisitions whose next undecided step requires a role the
501	    // principal holds, AND whose department is in their scope (unless they
502	    // hold scope:any).
503	    let scope_any = p.permissions.contains("scope:any");
504	    let dept_refs: Vec<String> = p.scopes.iter()
505	        .filter(|s| s.kind == ScopeKind::Department)
506	        .map(|s| s.reference.clone()).collect();
507	
508	    let rows: Vec<(Uuid,)> = sqlx::query_as(
509	        "SELECT DISTINCT r.id
510	         FROM requisitions r
511	         JOIN requisition_approval_instances i ON i.requisition_id = r.id
512	         JOIN requisition_approval_steps s ON s.instance_id = i.id
513	         WHERE r.status='pending_approval'
514	           AND i.status='in_progress'
515	           AND s.decision IS NULL
516	           AND s.sequence = (
517	               SELECT MIN(s2.sequence) FROM requisition_approval_steps s2
518	               WHERE s2.instance_id = i.id AND s2.decision IS NULL
519	           )
520	           AND s.required_role = ANY($1)
521	           AND ($2::bool OR r.department_id::text = ANY($3))
522	         ORDER BY r.id",
523	    )
524	    .bind(&p.roles)
525	    .bind(scope_any)
526	    .bind(&dept_refs)
527	    .fetch_all(pool).await?;
528	
529	    let mut out = Vec::new();
530	    for (id,) in rows { out.push(load_detail(pool, p, id).await?); }
531	    Ok(out)
532	}
