534	pub async fn load_detail(pool: &PgPool, p: &Principal, req_id: Uuid) -> Result<RequisitionDetail, ApiAppError> {
535	    let req: Option<(Uuid, String, String, Uuid, String, Uuid, Uuid, NaiveDate, String, i64, bool, Option<Uuid>)> =
536	        sqlx::query_as(
537	            "SELECT r.id, r.ref_code, r.status, r.requester_id, u.email,
538	                    r.site_id, r.department_id, r.needed_by, r.justification,
539	                    r.total_amount_cents, r.contains_controlled, r.workflow_id
540	             FROM requisitions r JOIN users u ON u.id = r.requester_id
541	             WHERE r.id = $1",
542	        ).bind(req_id).fetch_optional(pool).await?;
543	    let r = req.ok_or(ApiAppError::NotFound)?;
544	
545	    // Object-level read auth: requester themselves, an approver who holds
546	    // an approve permission and matching role/scope, or scope:any.
547	    let scope_any = p.permissions.contains("scope:any");
548	    let owner = p.user_id == r.3;
549	    let approver = p.permissions.contains("requisitions:approve");
550	    let dept_ok = scope_any
551	        || p.scopes.iter().any(|s| s.kind == ScopeKind::Department && s.reference == r.6.to_string());
552	    if !(owner || (approver && dept_ok) || scope_any) {
553	        return Err(ApiAppError::Forbidden("not authorized to view this requisition".into()));
554	    }
555	
556	    let lines: Vec<(Uuid, Uuid, String, String, i32, i64, i64, bool, Option<i32>)> = sqlx::query_as(
557	        "SELECT rl.id, rl.item_id, i.name, i.sku, rl.quantity, rl.unit_price_cents, rl.line_total_cents,
558	                c.controlled, st.on_hand
559	         FROM requisition_lines rl
560	         JOIN inventory_items i ON i.id = rl.item_id
561	         JOIN inventory_categories c ON c.id = i.category_id
562	         LEFT JOIN inventory_stock_by_site st ON st.item_id = rl.item_id AND st.site_id = $2
563	         WHERE rl.requisition_id = $1 ORDER BY rl.id",
564	    ).bind(req_id).bind(r.5).fetch_all(pool).await?;
565	
566	    let route: Vec<(i32, String, String, Option<String>, Option<Uuid>, Option<String>)> = sqlx::query_as(
567	        "SELECT s.sequence, n.label, s.required_role, s.decision, s.decided_by, s.reason
568	         FROM requisition_approval_steps s
569	         JOIN approval_nodes n ON n.id = s.node_id
570	         JOIN requisition_approval_instances i ON i.id = s.instance_id
571	         WHERE i.requisition_id = $1 ORDER BY s.sequence",
572	    ).bind(req_id).fetch_all(pool).await?;
573	
574	    let audit_rows: Vec<(chrono::DateTime<chrono::Utc>, Option<Uuid>, String, Option<String>)> = sqlx::query_as(
575	        "SELECT occurred_at, actor_user_id, event_kind, comment FROM requisition_audit
576	         WHERE requisition_id=$1 ORDER BY occurred_at",
577	    ).bind(req_id).fetch_all(pool).await?;
578	
579	    Ok(RequisitionDetail {
580	        id: r.0, ref_code: r.1, status: r.2, requester_id: r.3, requester_email: r.4,
581	        site_id: r.5, department_id: r.6, needed_by: r.7, justification: r.8,
582	        total_amount_cents: r.9, contains_controlled: r.10, workflow_id: r.11,
583	        lines: lines.into_iter().map(|l| RequisitionLine {
584	            id: l.0, item_id: l.1, item_name: l.2, sku: l.3,
585	            quantity: l.4, unit_price_cents: l.5, line_total_cents: l.6,
586	            controlled: l.7, on_hand: l.8.unwrap_or(0),
587	        }).collect(),
588	        route: route.into_iter().map(|s| RouteStep {
589	            sequence: s.0, label: s.1, required_role: s.2,
590	            decision: s.3, decided_by: s.4, reason: s.5,
591	        }).collect(),
592	        audit: audit_rows.into_iter().map(|a| AuditEntry {
593	            occurred_at: a.0, actor_user_id: a.1, event_kind: a.2, comment: a.3,
594	        }).collect(),
595	    })
596	}
