{"file_path": "/home/nahom/Desktop/Others/EaglePointAI/vibe-coding-projects/week-2/SilverOak/TASK-17/repo/proxy/nginx.prod.conf", "content": "worker_processes  1;
events { worker_connections 1024; }

http {
  include       mime.types;
  default_type  application/octet-stream;
  sendfile on;
  keepalive_timeout 65;

  # Hide nginx version in error pages and headers.
  server_tokens off;

  upstream silveroak_api { server backend-api:8080; }
  upstream silveroak_web { server frontend:80; }

  # DNS resolver for OCSP stapling.
  resolver 8.8.8.8 8.8.4.4 valid=300s;
  resolver_timeout 5s;

  # ── HTTP → HTTPS redirect ───────────────────────────────────────────────
  server {
    listen 80;
    server_name _;
    return 301 https://$host$request_uri;
  }

  # ── HTTPS (TLS termination) ─────────────────────────────────────────────
  # Cert files are mounted by docker-compose.prod.yml at /etc/nginx/certs/.
  # Expected layout:
  #   /etc/nginx/certs/fullchain.pem   — certificate + intermediates
  #   /etc/nginx/certs/privkey.pem     — private key (chmod 0600)
  server {
    listen 443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/certs/fullchain.pem;
    ssl_certificate_key /etc/nginx/certs/privkey.pem;

    # Protocols and ciphers — TLS 1.2 + 1.3 only; no RC4/3DES/MD5.
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384';
    ssl_prefer_server_ciphers off;

    # Session cache (improves reconnect performance).
    ssl_session_cache   shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;

    # OCSP stapling.
    ssl_stapling        on;
    ssl_stapling_verify on;

    # ── Security headers ─────────────────────────────────────────────────
    # HSTS: 2-year max-age, applied to all subdomains.
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
    # Deny framing entirely (clickjacking protection).
    add_header X-Frame-Options DENY always;
    # Prevent MIME sniffing.
    add_header X-Content-Type-Options nosniff always;
    # Limit referrer leakage.
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    # CSP: Yew WASM SPA served from the same origin; tune 'unsafe-inline'
    # for styles once a nonce/hash-based approach is in place.
    add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';" always;
    # Disable unnecessary browser features.
    add_header Permissions-Policy "geolocation=(), camera=(), microphone=(), payment=()" always;

    # ── Upstream proxying (identical routes to dev config) ────────────────
    location /api/ {
      proxy_pass http://silveroak_api;
      proxy_set_header Host $host;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    location / {
      proxy_pass http://silveroak_web;
      proxy_set_header Host $host;
    }
  }
}
"}

